  "claude-fable-5-1":          { input_per_1k: 0.010,   output_per_1k: 0.050, cache_read_per_1k: 0.00025 },
  "claude-opus-5":             { input_per_1k: 0.005,   output_per_1k: 0.025 },
  "claude-sonnet-5":           { input_per_1k: 0.002,   output_per_1k: 0.010 },
